const categories = (process.env.PROJECT_CATEGORIES || 'LLM,Generative AI,Machine Learning,Deep Learning,NLP,Transformers,Reinforcement Learning')
  .split(',').map(s => s.trim()).filter(Boolean);
const idx = (new Date().getDay() + 6) % 7;
const category = categories[idx % categories.length] || 'Generative AI';
const map = {
  'LLM': {github:'large language model LLM OR RAG OR agent', hf:'language model'},
  'Generative AI': {github:'generative AI OR diffusion OR multimodal', hf:'generative'},
  'Machine Learning': {github:'machine learning classification regression anomaly detection', hf:'tabular classification'},
  'Deep Learning': {github:'deep learning CNN computer vision neural network', hf:'image classification'},
  'NLP': {github:'NLP natural language processing sentiment NER text classification', hf:'text classification'},
  'Transformers': {github:'transformers BERT ViT encoder decoder attention', hf:'transformers'},
  'Reinforcement Learning': {github:'reinforcement learning DQN PPO Q-learning gymnasium', hf:'reinforcement learning'},
};
const cfg = map[category] || map['Generative AI'];
return [{json:{category, github_query:cfg.github, hf_query:cfg.hf, date:new Date().toISOString()}}];

const topic = $('Topic Router').first().json;
const gh = $('GitHub Search').first().json || {};
const models = $('HF Models Search').all().map(x => x.json).flat().slice(0, Number(process.env.MAX_SOURCE_ITEMS || 5));
const datasets = $('HF Datasets Search').all().map(x => x.json).flat().slice(0, Number(process.env.MAX_SOURCE_ITEMS || 5));
const allowed = new Set(['MIT','Apache-2.0','BSD-2-Clause','BSD-3-Clause','MPL-2.0','ISC','CC0-1.0']);
const github = (gh.items || []).map(r => ({
  type:'github', name:r.full_name, url:r.html_url, description:r.description,
  license:r.license?.spdx_id || null, stars:r.stargazers_count || 0,
  language:r.language || null,
})).filter(r => r.license && allowed.has(r.license)).slice(0, Number(process.env.MAX_SOURCE_ITEMS || 5));
const hfModels = models.map(m => ({type:'huggingface-model', name:m.id, url:`https://huggingface.co/${m.id}`,
  license:m.cardData?.license || m.license || null, pipeline_tag:m.pipeline_tag || null,
  downloads:m.downloads || 0, likes:m.likes || 0}));
const hfDatasets = datasets.map(d => ({type:'huggingface-dataset', name:d.id, url:`https://huggingface.co/datasets/${d.id}`,
  license:d.cardData?.license || d.license || null, downloads:d.downloads || 0, likes:d.likes || 0}));
return [{json:{...topic, sources:{github,huggingface_models:hfModels,huggingface_datasets:hfDatasets}}}];

const raw = $json?.choices?.[0]?.message?.content;
if (!raw) throw new Error('Groq planner returned no content');
let plan;
try { plan = JSON.parse(raw); } catch (e) {
  const cleaned = raw.replace(/^```json\s*/,'').replace(/^```\s*/,'').replace(/```$/,'').trim();
  plan = JSON.parse(cleaned);
}
const safe = v => typeof v === 'string' ? v.trim() : '';
plan.project_name = safe(plan.project_name) || 'AI Daily Project';
plan.repo_name = (safe(plan.repo_name) || plan.project_name.toLowerCase()).toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'').slice(0,80);
plan.files = Array.isArray(plan.files) ? plan.files : [];
plan.sources = Array.isArray(plan.sources) ? plan.sources : [];
return [{json:{...$('Source Pack').first().json, plan}}];

const base = $('Parse Plan').first().json;
const existing = $('Supabase Repo Check').all().map(x => x.json).flat();
let repo = base.plan.repo_name;
if (existing.length) repo = `${repo}-${new Date().toISOString().slice(0,10).replace(/-/g,'')}`;
base.plan.repo_name = repo;
base.plan.repo_name = base.plan.repo_name.slice(0,90);
return [{json:base}];

const base = $('Finalize Repo Name').first().json;
const check = $('GitHub Repo Check').first().json || {};
if (check.statusCode === 200 || check.body?.id) {
  base.plan.repo_name = `${base.plan.repo_name}-${Date.now().toString().slice(-6)}`;
}
return [{json:base}];

const raw = $json?.choices?.[0]?.message?.content;
if (!raw) throw new Error('Groq file writer returned no content');
let generated;
try { generated = JSON.parse(raw); } catch (e) {
  const cleaned = raw.replace(/^```json\s*/,'').replace(/^```\s*/,'').replace(/```$/,'').trim();
  generated = JSON.parse(cleaned);
}
const requested = $('Split Files').item.json.files;
if (requested.path === '.github/workflows/ci.yml' && requested.static_content) generated.content = requested.static_content;
generated.path = requested.path;
if (typeof generated.content !== 'string') generated.content = String(generated.content ?? '');
if (generated.content.length > 800000) throw new Error(`Generated file too large: ${generated.path}`);
return [{json:{...$('Split Files').item.json, generated_file:generated}}];

const g = $json.generated_file;
const safePath = g.path.replace(/^\/+/, '').split('/').filter(p => p && p !== '.' && p !== '..').join('/');
if (!safePath || safePath.length > 240) throw new Error('Unsafe or invalid repository path');
const payload = {
  message: `feat: add ${safePath}`,
  content: Buffer.from(g.content, 'utf8').toString('base64'),
};
return [{json:{...$json, github_path:safePath, github_payload:payload}}];

const base = $('Prepare Publish Record').first().json;
const repo = base.plan.repo_name;
const owner = process.env.GITHUB_OWNER;
const uploadResults = $('Upload File to GitHub').all().map(x => x.json);
const failed = uploadResults.find(r => (r.statusCode || 200) >= 400 || r.body?.message?.toLowerCase()?.includes('error'));
const repoUrl = `https://github.com/${owner}/${repo}`;
return [{json:{
  project_name:base.plan.project_name,
  repo_name:repo,
  category:base.category,
  github_url:repoUrl,
  upload_count:uploadResults.length,
  upload_ok:!failed,
  upload_results:uploadResults.slice(-3),
  generation_run_id:$execution.id,
  plan:base.plan,
  status:failed ? 'failed_upload' : 'published',
  published_at:new Date().toISOString()
}}];

